addon.translation = {
-- 3adec7ba English: Damage (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: DpsIcyVeins). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1] = "Schaden (Icy Veins)",
-- 9b0711bb English: Damage from level 1 to 70, used whenever the healer premade does not apply.
--     Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric
--     Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is
--     wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner
--     Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is
--     cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and
--     healing stay with you.
[2] = "Schaden von Stufe 1 bis 70, verwendet, wann immer die integrierte Heilerrotation nicht greift. Anfangs Göttliche Pein und Zauberstab, dann Gedankenschlag, Schattenwort: Schmerz, Gedankenschinden, Schattengestalt, Vampirberührung und Schattenwort: Tod, sobald Sie sie erlernen; DoTs vor Gedankenschlag; ein sterbendes Ziel wird beim Solospiel mit dem Zauberstab erledigt. Heilig- und Disziplin-Priester beim Questen erhalten Heiliges Feuer und Göttliche Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Volks-Stärkungszauber, Innerer Fokus, Schattengeist. Ein Gedankenschinden nach seinem ersten Tick wird für einen bereiten Gedankenschlag abgebrochen, oder für Schattenwort: Tod über halber Gesundheit. Schilde und Heilung bleiben Ihnen überlassen.",
-- ce79d246 English: Damage (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: DpsWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[3] = "Schaden (Wowhead)",
-- fe006eaa English: Damage after Wowhead's guides, an alternative to the recommended Icy Veins
--     damage premade, off by default: enable it and disable that one, or raise its priority. Mind
--     Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and
--     a dying target gets spells instead of the wand. Otherwise the same as the recommended
--     premade.
[4] = "Schaden nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Schadensrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag eröffnet und kommt vor dem Erneuern der DoTs, Vampirumarmung nur, wenn Ihre Gesundheit sinkt, und ein sterbendes Ziel erhält Zauber statt des Zauberstabs. Ansonsten wie die empfohlene integrierte Rotation.",
-- d0f0e9e6 English: Healer (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: HealerWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[5] = "Heiler (Wowhead)",
-- d31781e0 English: Healing in a group when Holy or Discipline is your main talent tree. It advises
--     on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and
--     whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or
--     Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1
--     as a cheap top-up. With an enemy targeted it offers light damage.
[6] = "Heilung in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist. Sie berät zu der freundlichen Einheit, die Sie anvisieren; wen Sie heilen, entscheiden Sie. Gebet der Besserung vor Pulls und sobald bereit, Erneuerung, Machtwort: Schild im Notfall, Bannungen, Kreis der Heilung oder Gebet der Heilung bei Gruppenschaden, Verbindende Heilung, Blitzheilung und Große Heilung sowie Große Heilung Rang 1 als günstiges Auffüllen. Mit einem anvisierten Gegner bietet sie leichten Schaden an.",
-- 45321807 English: Healer (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: HealerIcyVeins). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[7] = "Heiler (Icy Veins)",
-- e31d4277 English: Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash
--     Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to
--     heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and
--     disable that one, or raise its priority.
[8] = "Heilung in der Reihenfolge von Icy Veins: Schild, Bannungen, Verbindende Heilung, Erneuerung, Blitzheilung, Große Heilung (beliebiger Rang), Gruppenheilungen und zuletzt Gebet der Besserung. Wen Sie heilen, entscheiden Sie. Eine Alternative zur empfohlenen integrierten Heilerrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- e64b45e0 English: Shadow and solo damage
[9] = "Schatten und Solo-Schaden",
-- 4394336c English: Shadow, and every Priest's solo play, from level 1 to 60; the Forever Priest
--     default. Pulls with Power Word: Shield (solo) and Mind Blast (Holy Fire for Holy and
--     Discipline, Smite before Mind Blast). Then Shadowform once learned, your own Shadow Word:
--     Pain and Devouring Plague, Mind Blast, Holy Fire into Penance for Discipline, Mind Flay in
--     Shadowform; solo before Shadowform, Holy Nova on three enemies with Holy Purpose, then the
--     wand (Smite without one). Moving: Pain, Plague. Reminders: Inner Fire, Fortitude, Divine
--     Spirit, racial buffs, Vampiric Embrace, Inner Focus, Silence, Elune's Light; Psychic Scream
--     is off by default. Health and mana are hidden from addons on Forever, so executing with
--     Shadow Word: Death, healing yourself and Dark Sacrifice are your call. Built from level-30
--     beta guides; Shadowform play follows Mobalytics.
[10] = "Schatten und das Solospiel jedes Priesters, von Stufe 1 bis 60; der Forever-Priester-Standard. Zieht mit Machtwort: Schild (solo) und Gedankenschlag (Heiliges Feuer für Heilig und Disziplin, Heilige Pein vor Gedankenschlag). Dann Schattengestalt, sobald erlernt, Ihr eigenes Schattenwort: Schmerz und Ihre Verschlingende Seuche, Gedankenschlag, Heiliges Feuer in Sühne für Disziplin, Gedankenschinden in Schattengestalt; solo vor Schattengestalt Heilige Nova gegen drei Gegner mit Heiliger Zweck, dann der Zauberstab (Heilige Pein ohne einen). In Bewegung: Schmerz, Seuche. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Volks-Stärkungszauber, Vampirumarmung, Innerer Fokus, Stille, Elunes Licht; Psychischer Schrei ist standardmäßig deaktiviert. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über das Erledigen mit Schattenwort: Tod, Selbstheilung und Dunkles Opfer. Erstellt aus Beta-Leitfäden für Stufe 30; das Spiel in Schattengestalt folgt Mobalytics.",
-- 05426e5b English: DoT and wand leveling (Mobalytics)
[11] = "DoT- und Zauberstab-Leveling (Mobalytics)",
-- df96ccf0 English: Mobalytics' leveling style, an alternative to the recommended Shadow premade,
--     off by default: enable it and disable that one, or raise its priority. Mind Blast and Holy
--     Fire only on tough mobs (elites, or two levels above you), your own Shadow Word: Pain and
--     Devouring Plague, then the wand (Smite without one). From Shadowform: Mind Blast, Pain,
--     Plague, Mind Flay. Shield and Renew on yourself between pulls, Cure Disease on yourself.
--     Health and mana are hidden from addons on Forever, so healing yourself is your call.
--     Spreading Pain across several mobs is up to you.
[12] = "Levelstil von Mobalytics, eine Alternative zur empfohlenen integrierten Schattenrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag und Heiliges Feuer nur gegen zähe Gegner (Elitegegner oder zwei Stufen über Ihnen), Ihr eigenes Schattenwort: Schmerz und Ihre Verschlingende Seuche, dann der Zauberstab (Heilige Pein ohne einen). Ab Schattengestalt: Gedankenschlag, Schmerz, Seuche, Gedankenschinden. Schild und Erneuerung auf sich selbst zwischen Pulls, Krankheit heilen auf sich selbst. Gesundheit und Mana sind für Addons unter Forever verborgen, daher bleibt die Selbstheilung Ihnen überlassen. Grassierender Schmerz über mehrere Gegner bleibt Ihnen überlassen.",
-- ef4ae5d0 English: Discipline and Holy healing
[13] = "Disziplin- und Heilig-Heilung",
-- 787c3a6e English: Group healing once Discipline or Holy is your main talent tree and you do not
--     know Shadowform. Heals your current friendly target: before the pull Power Word: Shield,
--     Prayer of Mending and Renew; Dispel Magic and Abolish or Cure Disease; Prayer of Mending;
--     Holy Nova on Holy Purpose; Penance; Renew when missing; Heal (Lesser Heal before it). On an
--     enemy: Shadow Word: Pain, Holy Fire, Penance, Smite, wand. Reminders: Inner Fire, Fortitude,
--     Divine Spirit, Power Infusion on another player, Inner Focus in combat and the racial spells.
--     Health and mana are hidden from addons on Forever, so the target you pick is the only sign of
--     who needs healing; emergency heals, Prayer of Healing, Binding Heal, Greater and Flash Heal,
--     Desperate Prayer and Dark Sacrifice are your call. You pick who to heal and the rank; a
--     Discipline healer before Penance (20–29) selects it by hand.
[14] = "Gruppenheilung, sobald Disziplin oder Heilig Ihr Haupttalentbaum ist und Sie Schattengestalt nicht beherrschen. Heilt Ihr aktuelles freundliches Ziel: vor dem Pull Machtwort: Schild, Gebet der Besserung und Erneuerung; Magiebannung und Krankheit aufheben oder Krankheit heilen; Gebet der Besserung; Heilige Nova bei Heiliger Zweck; Sühne; Erneuerung, wenn sie fehlt; Heilen (davor Geringes Heilen). Gegen einen Gegner: Schattenwort: Schmerz, Heiliges Feuer, Sühne, Heilige Pein, Zauberstab. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Seele der Macht auf einen anderen Spieler, Innerer Fokus im Kampf und die Volkszauber. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht; Notheilungen, Gebet der Heilung, Verbindende Heilung, Große Heilung und Blitzheilung, Verzweifeltes Gebet und Dunkles Opfer bleiben Ihnen überlassen. Wen Sie heilen und den Rang wählen Sie; ein Disziplin-Heiler vor Sühne (20–29) wählt diese Rotation von Hand aus.",
-- e88d5282 English: Recommended for Shadow in Midnight. In combat the game now hides your DoTs,
--     buffs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat
--     suggestion (the one-button rotation, which keeps your DoTs, Shadowform and Voidform going and
--     lets Mind Flay finish), and stops while you cast or have no enemy targeted. Reminders for
--     what it leaves out: Power Infusion in the 20 seconds after you cast Voidform, Shadowform and
--     Power Word: Fortitude between pulls, Silence on an interruptible cast (it lights only where
--     the game lets the cast be read). Health is hidden on Retail, so Desperate Prayer is your
--     call.
[15] = "Empfohlen für Schatten in Midnight. Im Kampf verbirgt das Spiel nun Ihre DoTs, Stärkungszauber, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die Ihre DoTs, Schattengestalt und Leerengestalt aufrechterhält und Gedankenschinden zu Ende kanalisieren lässt) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Seele der Macht in den 20 Sekunden, nachdem Sie Leerengestalt gewirkt haben, Schattengestalt und Machtwort: Seelenstärke zwischen den Kämpfen, Stille bei einem unterbrechbaren Zauber (sie leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt). Die Gesundheit ist unter Retail verborgen, daher bleibt Verzweifeltes Gebet Ihnen überlassen.",
-- 1cbf9308 English: Reference only, off by default: the Icy Veins and SimulationCraft order reads
--     DoT timers, Madness and Voidform, which Midnight hides in combat; Insanity and health are
--     hidden on Retail, so the Insanity-cap Madness, the Shadow Word: Death execute and Desperate
--     Prayer are left to you. Vampiric Touch before the pull; Tentacle Slam to apply Vampiric
--     Touch; Vampiric Touch and Shadow Word: Pain refreshed in their last 30%; Shadow Word: Madness
--     when it is ending or in Voidform; Void Blast during Madness; Tentacle Slam at two charges;
--     Void Torrent; Mind Blast; Tentacle Slam; Mind Flay: Insanity during Madness; Void Volley;
--     Death and Pain while moving; Mind Flay, clipped for a ready Mind Blast. Reminders: Halo,
--     Voidform with both DoTs up, Power Infusion in Voidform.
[16] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest DoT-Timer, den Effekt Wahnsinn und Leerengestalt, die Midnight im Kampf verbirgt; Wahnsinn (die Ressource) und Gesundheit sind unter Retail verborgen, daher bleiben Schattenwort: Wahnsinn am Wahnsinn-Maximum, das Erledigen mit Schattenwort: Tod und Verzweifeltes Gebet Ihnen überlassen. Vampirberührung vor dem Pull; Tentakelschlag, um Vampirberührung aufzubringen; Vampirberührung und Schattenwort: Schmerz in ihren letzten 30 % erneuert; Schattenwort: Wahnsinn, wenn es ausläuft oder während Leerengestalt; Leerenschlag während des Effekts Wahnsinn; Tentakelschlag bei zwei Aufladungen; Leerenstrom; Gedankenschlag; Tentakelschlag; Gedankenschinden: Wahnsinn während des Effekts Wahnsinn; Leerensalve; Schattenwort: Tod und Schattenwort: Schmerz in Bewegung; Gedankenschinden, abgebrochen, sobald Gedankenschlag bereit ist. Erinnerungen: Strahlenkranz, Leerengestalt mit beiden aktiven DoTs, Seele der Macht während Leerengestalt.",
-- 6a76d2e3 English: Atonement (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     Retail (current expansion) (variant key: Discipline). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[17] = "Abbitte (Icy Veins)",
-- c8fa3896 English: Discipline in Midnight, for reference: Blizzard's Assisted Combat does not
--     cover healers, the game hides everyone's health in combat and Rotation Master picks a spell,
--     not a target, so this runs the damage that heals through Atonement and leaves deciding who to
--     heal to you. On a friendly target: Power Word: Shield (Void Shield), Penance, Flash Heal. On
--     an enemy: Shadow Word: Pain when you have not cast it for 12 seconds, Mind Blast, Penance,
--     Shield, Shadow Word: Death, Void Blast, Smite. Reminders in combat: Power Word: Radiance,
--     Evangelism, Ultimate Penitence, Pain Suppression on a friendly target; Fortitude between
--     pulls. Desperate Prayer is your call. Raid ramps before big damage are yours to time.
[18] = "Disziplin in Midnight, als Referenz: Blizzards Kampfassistent deckt keine Heiler ab, das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher spielt diese Rotation den Schaden, der über Abbitte heilt, und überlässt Ihnen die Entscheidung, wen Sie heilen. Bei einem freundlichen Ziel: Machtwort: Schild (Leerenschild), Sühne, Blitzheilung. Bei einem Gegner: Schattenwort: Schmerz, wenn Sie es 12 Sekunden lang nicht gewirkt haben, Gedankenschlag, Sühne, Schild, Schattenwort: Tod, Leerenschlag, Heilige Pein. Erinnerungen im Kampf: Machtwort: Glanz, Prediger, Ultimative Bußfertigkeit, Schmerzunterdrückung auf einem freundlichen Ziel; Seelenstärke zwischen den Kämpfen. Verzweifeltes Gebet bleibt Ihnen überlassen. Das Timing von Schlachtzugs-Ramps vor großem Schaden liegt bei Ihnen.",
-- db649bbf English: Death first reference (Wowhead)
[19] = "Schattenwort: Tod zuerst, Referenz (Wowhead)",
-- e33c171d English: Reference only, off by default: Wowhead's Season 1 Oracle order, which keeps
--     Shadow Word: Pain up by reading the debuff that Midnight hides in combat. Shadow Word: Pain,
--     Shadow Word: Death on cooldown, Penance, Mind Blast, Smite; Penance first on a friendly
--     target. Same reminders as the Icy Veins premade.
[20] = "Nur als Referenz, standardmäßig deaktiviert: die Orakel-Reihenfolge von Wowhead für Saison 1, die Schattenwort: Schmerz aufrechterhält, indem sie den Schwächungszauber ausliest, den Midnight im Kampf verbirgt. Schattenwort: Schmerz, Schattenwort: Tod bei Abklingzeit-Ende, Sühne, Gedankenschlag, Heilige Pein; bei einem freundlichen Ziel zuerst Sühne. Dieselben Erinnerungen wie die integrierte Rotation nach Icy Veins.",
-- d7f52f6f English: Holy in Midnight, for reference: the game hides everyone's health in combat and
--     Rotation Master picks a spell, not a target, so this keeps your Holy Words, Prayer of Mending
--     and procs moving on whatever you target and leaves triage to you. On a friendly target: Holy
--     Word: Sanctify, Holy Word: Serenity, Prayer of Mending, Prayer of Healing with Surge of
--     Light, Benediction, Prayer of Healing with Lightweaver, Flash Heal with Surge of Light,
--     Prayer of Healing in a group, Holy Nova while moving, Flash Heal. On an enemy: Holy Word:
--     Chastise, Holy Fire, Holy Nova while moving, Smite. Reminders: Apotheosis, Divine Hymn and
--     Halo in combat, Guardian Spirit on a friendly target (health is hidden on Retail, so whether
--     it is about to die is your call), Fortitude. Desperate Prayer is yours.
[21] = "Heilig in Midnight, als Referenz: Das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher hält diese Rotation Ihre Segensworte, Gebet der Besserung und Procs auf jedem Ziel, das Sie anvisieren, in Gang und überlässt Ihnen die Triage. Bei einem freundlichen Ziel: Segenswort: Heiligung, Segenswort: Epiphanie, Gebet der Besserung, Gebet der Heilung mit Woge des Lichts, Segnung, Gebet der Heilung mit Lichtweber, Blitzheilung mit Woge des Lichts, Gebet der Heilung in einer Gruppe, Heilige Nova in Bewegung, Blitzheilung. Bei einem Gegner: Segenswort: Züchtigung, Heiliges Feuer, Heilige Nova in Bewegung, Heilige Pein. Erinnerungen: Apotheose, Gotteshymne und Strahlenkranz im Kampf, Schutzgeist auf einem freundlichen Ziel (die Gesundheit ist unter Retail verborgen, daher bleibt es Ihnen überlassen, ob es kurz vor dem Tod steht), Seelenstärke. Verzweifeltes Gebet bleibt Ihnen überlassen.",
-- 4b29903d English: Recommended before you choose a specialization (while the game reports the
--     Priest's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Priest premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[22] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Priesters meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Priester-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- 0c874f58 English: Damage
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     Classic Era (variant key: Dps).
[23] = "Schaden",
-- 3af8cf40 English: Damage from level 1 to 60, and the Priest default whenever the healer premade
--     does not apply (solo, Shadow, or no talents yet). Shadowform when learned; before a pull a
--     shield when solo, then Holy Fire (without Shadowform), Mind Blast or Smite. Shadow Word: Pain
--     once per target that will live, Mind Blast on cooldown, Mind Flay as the filler (Smite and
--     Holy Nova before you have it), and the wand on a dying target or when your mana runs low
--     while solo. Vampiric Embrace and Devouring Plague on long fights, never in raids. Reminders:
--     Inner Fire, Fortitude, racial buffs, Inner Focus with Mind Blast, Psychic Scream when two
--     enemies reach you at half health, Fade when your target turns on you, Desperate Prayer.
--     Target choice, multi-dotting and downranking stay with you.
[24] = "Schaden von Stufe 1 bis 60 und der Priester-Standard, wann immer die integrierte Heilerrotation nicht greift (solo, Schatten oder noch keine Talente). Schattengestalt, sobald erlernt; vor einem Pull solo ein Schild, dann Heiliges Feuer (ohne Schattengestalt), Gedankenschlag oder Göttliche Pein. Schattenwort: Schmerz einmal pro Ziel, das lange genug lebt, Gedankenschlag bei Abklingzeit-Ende, Gedankenschinden als Füller (Göttliche Pein und Heilige Nova, bevor Sie es haben) und der Zauberstab auf ein sterbendes Ziel oder bei knappem Mana im Solospiel. Vampirumarmung und Verschlingende Seuche bei langen Kämpfen, nie in Schlachtzügen. Erinnerungen: Inneres Feuer, Seelenstärke, Volks-Stärkungszauber, Innerer Fokus mit Gedankenschlag, Psychischer Schrei, wenn zwei Gegner Sie bei halber Gesundheit erreichen, Verblassen, wenn Ihr Ziel Sie angreift, Verzweifeltes Gebet. Zielwahl, DoTs auf mehreren Zielen und Herabstufen von Rängen bleiben Ihnen überlassen.",
-- 7cf48919 English: Damage (Warcraft Tavern wand economy)
[25] = "Schaden (Warcraft Tavern, Zauberstab-Ökonomie)",
-- a52bcaac English: Warcraft Tavern's low-downtime leveling style, an alternative to the
--     recommended damage premade, off by default: enable it and disable that one, or raise its
--     priority. Solo: Mind Blast to pull, Shadow Word: Pain once, Mind Blast again only while the
--     target is above 30%, and your wand between Mind Blasts instead of Smite or Mind Flay. No
--     automatic shield before pulls. In a group: Shadow Word: Pain, Mind Blast, Mind Flay. Same
--     reminders as the recommended premade.
[26] = "Der Leveling-Stil von Warcraft Tavern mit wenig Pausen, eine Alternative zur empfohlenen integrierten Schadensrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solo: Gedankenschlag zum Ziehen, einmal Schattenwort: Schmerz, erneut Gedankenschlag nur, solange das Ziel über 30 % liegt, und Ihr Zauberstab zwischen den Gedankenschlägen statt Göttlicher Pein oder Gedankenschinden. Kein automatischer Schild vor Pulls. In einer Gruppe: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
-- 545a097f English: Damage (simulator Undead raid)
[27] = "Schaden (Simulation, Untote im Schlachtzug)",
-- 589927b7 English: The recommended damage priority with simulator' raid choice for Undead priests:
--     Inner Focus is spent on Devouring Plague instead of Mind Blast, and Devouring Plague is cast
--     in raids too, so use it only where your raid has debuff slots to spare. No Vampiric Embrace.
--     An alternative to the recommended damage premade, off by default: enable it and disable that
--     one, or raise its priority.
[28] = "Die empfohlene Schadenspriorität mit der Schlachtzugswahl von Simulation für untote Priester: Innerer Fokus wird für Verschlingende Seuche statt Gedankenschlag eingesetzt, und Verschlingende Seuche wird auch in Schlachtzügen gewirkt, nutzen Sie sie also nur, wo Ihr Schlachtzug freie Plätze für Schwächungszauber hat. Keine Vampirumarmung. Eine Alternative zur empfohlenen integrierten Schadensrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- dae36c27 English: Chosen in a group when Holy or Discipline is your main talent tree. Heals the
--     friendly unit you target: Power Word: Shield below 30%, Flash Heal below 40%, dispels, Prayer
--     of Healing when three of your party are hurt, Greater Heal (Heal or Lesser Heal before you
--     learn it) below half health, Renew while moving or on light damage, then Heal rank 3 as the
--     efficient top-up. Out of combat it offers Fortitude on your target. Targeting an enemy gives
--     Shadow Word: Pain and Smite. Reminders: Inner Fire, Fortitude, Divine Spirit, Inner Focus,
--     Desperate Prayer; Power Infusion is off by default. Choosing whom to heal and downranking
--     stay with you.
[29] = "Gewählt in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist. Heilt die freundliche Einheit, die Sie anvisieren: Machtwort: Schild unter 30 %, Blitzheilung unter 40 %, Bannungen, Gebet der Heilung, wenn drei Ihrer Gruppe verletzt sind, Große Heilung (Heilen oder Geringes Heilen, bevor Sie sie erlernen) unter halber Gesundheit, Erneuerung in Bewegung oder bei leichtem Schaden, dann Heilen Rang 3 als effizientes Auffüllen. Außerhalb des Kampfes bietet sie Seelenstärke auf Ihr Ziel an. Ein anvisierter Gegner erhält Schattenwort: Schmerz und Göttliche Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Göttlicher Willen, Innerer Fokus, Verzweifeltes Gebet; Seele der Macht ist standardmäßig deaktiviert. Wen Sie heilen und das Herabstufen von Rängen bleiben Ihnen überlassen.",
-- 999e9eba English: Damage (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     Season of Discovery (variant key: Dps). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[30] = "Schaden (SoD)",
-- 63f3ee22 English: Damage on Season of Discovery realms, from level 1 to 60, using the runes you
--     have engraved. Shadowform; Vampiric Touch or Mind Blast to pull (Penance, Holy Fire or Smite
--     before Shadowform). Void Plague, Shadow Word: Pain and Vampiric Touch kept up (refreshed near
--     the end only without Pain and Suffering engraved), Mind Blast on cooldown, Mind Flay on
--     Melting Faces, Shadow Word: Death while you are above half health, then Mind Spike as the
--     filler, or Mind Flay with the Phase 8 six-piece set. Void Zone and Mind Sear on four or more
--     enemies. The wand on a dying solo target. Reminders: Inner Fire, Fortitude, Homunculi,
--     Shadowfiend, Eye of the Void and Dispersion, Inner Focus, Psychic Scream, Fade, Desperate
--     Prayer.
[31] = "Schaden auf Realms der Saison der Entdeckungen von Stufe 1 bis 60 mit den Runen, die Sie graviert haben. Schattengestalt; Vampirberührung oder Gedankenschlag zum Ziehen (Sühne, Heiliges Feuer oder Göttliche Pein vor Schattengestalt). Pest der Leere, Schattenwort: Schmerz und Vampirberührung aufrechterhalten (nur ohne die Rune „Pain and Suffering“ gegen Ende erneuert), Gedankenschlag bei Abklingzeit-Ende, Gedankenschinden bei Gesichter schmelzen, Schattenwort: Tod, solange Sie über halber Gesundheit sind, dann Gedankenstachel als Füller oder Gedankenschinden mit dem Sechsteile-Set aus Phase 8. Zone der Leere und Gedankenbrand gegen vier oder mehr Gegner. Der Zauberstab auf ein sterbendes Ziel im Solospiel. Erinnerungen: Inneres Feuer, Seelenstärke, Homunculi, Schattengeist, Auge der Leere und Dispersion, Innerer Fokus, Psychischer Schrei, Verblassen, Verzweifeltes Gebet.",
-- 57985f5a English: Damage (SoD, Wowhead Mind Spike stacks)
[32] = "Schaden (SoD, Wowhead, Stapel von Gedankenstachel)",
-- 296f399b English: The Wowhead and Warcraft Tavern way for Season of Discovery, an alternative to
--     the recommended Season of Discovery damage premade, off by default: enable it and disable
--     that one, or raise its priority. Mind Blast waits for three of your Mind Spike stacks on the
--     target (it is cast normally until you engrave Mind Spike), Mind Flay only on Melting Faces,
--     Mind Spike as the filler. Everything else matches the recommended premade.
[33] = "Die Spielweise von Wowhead und Warcraft Tavern für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Schadensrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag wartet auf drei Ihrer Stapel von Gedankenstachel auf dem Ziel (bis Sie Gedankenstachel gravieren, wird er normal gewirkt), Gedankenschinden nur bei Gesichter schmelzen, Gedankenstachel als Füller. Alles andere entspricht der empfohlenen integrierten Rotation.",
-- 37b39f3b English: Chosen on Season of Discovery realms in a group when Holy or Discipline is your
--     main talent tree; follows Icy Veins. Heals the friendly unit you target: Prayer of Mending
--     before the pull and whenever ready, Shield below half health, Penance, instant Flash Heal on
--     Surge of Light, emergency Flash Heal, dispels, Circle of Healing and Prayer of Healing when
--     three of your party are hurt, Greater Heal below half health, Renew while moving or on light
--     damage, then Heal. Targeting an enemy gives Pain, Void Plague, Penance, Holy Fire and Smite.
--     Reminders include Shadowfiend, Pain Suppression on a dying target, Power Word: Barrier and
--     Spirit of the Redeemer when the party is hurt.
[34] = "Gewählt auf Realms der Saison der Entdeckungen in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist; folgt Icy Veins. Heilt die freundliche Einheit, die Sie anvisieren: Gebet der Besserung vor dem Pull und sobald bereit, Schild unter halber Gesundheit, Sühne, sofortige Blitzheilung bei Woge des Lichts, Blitzheilung im Notfall, Bannungen, Kreis der Heilung und Gebet der Heilung, wenn drei Ihrer Gruppe verletzt sind, Große Heilung unter halber Gesundheit, Erneuerung in Bewegung oder bei leichtem Schaden, dann Heilen. Ein anvisierter Gegner erhält Schmerz, Pest der Leere, Sühne, Heiliges Feuer und Göttliche Pein. Zu den Erinnerungen gehören Schattengeist, Schmerzunterdrückung auf ein sterbendes Ziel, Machtwort: Barriere und Geist des Erlösers, wenn die Gruppe verletzt ist.",
-- 60216631 English: Healer (SoD, Warcraft Tavern)
[35] = "Heiler (SoD, Warcraft Tavern)",
-- 25158fb1 English: Warcraft Tavern's Serendipity loop, built for Serendipity and Soul Warding, an
--     alternative to the recommended Season of Discovery healer premade, off by default: enable it
--     and disable that one, or raise its priority. Prayer of Mending on cooldown, Shield on your
--     target whenever it can take one (with Soul Warding engraved; else below half health), Penance
--     on heavy damage, Circle of Healing for three hurt, Greater Heal or Prayer of Healing at three
--     Serendipity stacks, Renew on minor damage, and Flash Heal on minor injuries to build the
--     stacks (with Serendipity engraved; else below 30%).
[36] = "Die Glücksfall-Schleife von Warcraft Tavern, ausgelegt auf Glücksfall und Seelenwehr, eine Alternative zur empfohlenen integrierten Heilerrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gebet der Besserung bei Abklingzeit-Ende, Schild auf Ihr Ziel, wann immer es einen erhalten kann (mit eingravierter Rune Seelenwehr; sonst unter halber Gesundheit), Sühne bei hohem Schaden, Kreis der Heilung bei drei Verletzten, Große Heilung oder Gebet der Heilung bei drei Stapeln Glücksfall, Erneuerung bei geringem Schaden und Blitzheilung bei kleinen Verletzungen, um die Stapel aufzubauen (mit eingravierter Rune Glücksfall; sonst unter 30 %).",
-- 360a55ef English: Discipline healing from level 10 to 90, chosen in the Discipline
--     specialization. Target a friend to heal them: Power Word: Shield when they are low, before
--     the pull and about every 12 seconds for Rapture; Flash Heal on Surge of Light; Penance; Flash
--     Heal when they are very low; Binding Heal when you are both hurt; Prayer of Mending; Prayer
--     of Healing and your tier-6 talent when three allies are hurt; Greater Heal; Renew while
--     moving; Heal to top up. Under Spirit Shell it suggests Prayer of Healing or Greater Heal.
--     Target an enemy to heal through Atonement: Penance, Power Word: Solace or Holy Fire, your
--     tier-6 talent on packs, Shadow Word: Pain when solo, Smite. Reminders: Inner Fire, Fortitude,
--     Archangel at five Evangelism, Inner Focus, Pain Suppression on a dying target, Shadowfiend or
--     Mindbender for mana, Power Infusion, Desperate Prayer. Left to you: whom to heal, Spirit
--     Shell timing (a reminder you can switch on), Power Word: Barrier, Void Shift and Grace stacks
--     on the tank.
[37] = "Disziplin-Heilung von Stufe 10 bis 90, gewählt in der Spezialisierung Disziplin. Visieren Sie einen Verbündeten an, um ihn zu heilen: Machtwort: Schild, wenn er wenig Gesundheit hat, vor dem Pull und etwa alle 12 Sekunden für Euphorie; Blitzheilung bei Woge des Lichts; Sühne; Blitzheilung, wenn er sehr wenig Gesundheit hat; Verbindende Heilung, wenn Sie beide verletzt sind; Gebet der Besserung; Gebet der Heilung und Ihr Talent der Stufe 6, wenn drei Verbündete verletzt sind; Große Heilung; Erneuerung in Bewegung; Heilung zum Auffüllen. Während Geisthülle schlägt sie Gebet der Heilung oder Große Heilung vor. Visieren Sie einen Gegner an, um über Abbitte zu heilen: Sühne, Machtwort: Trost oder Heiliges Feuer, Ihr Talent der Stufe 6 gegen Gruppen, Schattenwort: Schmerz solo, Heilige Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Erzengel bei fünf Stapeln Prediger, Innerer Fokus, Schmerzunterdrückung auf ein sterbendes Ziel, Schattengeist oder Geistbeuger für Mana, Seele der Macht, Verzweifeltes Gebet. Ihnen überlassen: wen Sie heilen, das Timing von Geisthülle (eine Erinnerung, die Sie aktivieren können), Machtwort: Barriere, Leerenverschiebung und Stapel von Barmherzigkeit auf dem Tank.",
-- 1d7fb6cd English: Holy healing from level 10 to 90, chosen in the Holy specialization. Target a
--     friend to heal them: Holy Word: Serenity in Chakra: Serenity; Power Word: Shield only when
--     they are about to die; Flash Heal on Surge of Light; Prayer of Mending; Flash Heal when very
--     low; Binding Heal when you are both hurt; in a group with three allies hurt, Circle of
--     Healing, Holy Word: Sanctuary in Chakra: Sanctuary, your tier-6 talent and Prayer of Healing;
--     Renew; Greater Heal when low or at two Serendipity; Heal. Target an enemy to deal damage:
--     Holy Word: Chastise, Power Word: Solace or Holy Fire, Shadow Word: Pain when solo, your
--     tier-6 talent on packs, Smite. An empty chakra is filled for you (Sanctuary in a raid,
--     Serenity in a party, Chastise solo) and never swapped. Reminders: Inner Fire, Fortitude,
--     Guardian Spirit on a dying target, Divine Hymn when five allies are badly hurt, Shadowfiend
--     or Mindbender for mana, Power Infusion, Desperate Prayer. Left to you: whom to heal, placing
--     Holy Word: Sanctuary, Lightwell and Void Shift.
[38] = "Heilig-Heilung von Stufe 10 bis 90, gewählt in der Spezialisierung Heilig. Visieren Sie einen Verbündeten an, um ihn zu heilen: Segenswort: Epiphanie in Chakra: Epiphanie; Machtwort: Schild nur, wenn er kurz vor dem Tod steht; Blitzheilung bei Woge des Lichts; Gebet der Besserung; Blitzheilung bei sehr wenig Gesundheit; Verbindende Heilung, wenn Sie beide verletzt sind; in einer Gruppe mit drei verletzten Verbündeten Kreis der Heilung, Segenswort: Refugium in Chakra: Refugium, Ihr Talent der Stufe 6 und Gebet der Heilung; Erneuerung; Große Heilung bei wenig Gesundheit oder bei zwei Stapeln Glücksfall; Heilung. Visieren Sie einen Gegner an, um Schaden zu verursachen: Segenswort: Züchtigung, Machtwort: Trost oder Heiliges Feuer, Schattenwort: Schmerz solo, Ihr Talent der Stufe 6 gegen Gruppen, Heilige Pein. Ein leeres Chakra wird für Sie gefüllt (Refugium im Schlachtzug, Epiphanie in einer Gruppe, Züchtigung solo) und nie gewechselt. Erinnerungen: Inneres Feuer, Seelenstärke, Schutzgeist auf ein sterbendes Ziel, Gotteshymne, wenn fünf Verbündete schwer verletzt sind, Schattengeist oder Geistbeuger für Mana, Seele der Macht, Verzweifeltes Gebet. Ihnen überlassen: wen Sie heilen, das Platzieren von Segenswort: Refugium, Lichtbrunnen und Leerenverschiebung.",
-- 87cd5cd8 English: Emergency heals last (Icy Veins)
[39] = "Notfallheilungen zuletzt (Icy Veins)",
-- 007307b5 English: Off by default. Icy Veins' Holy order, picked by your chakra. In Chakra:
--     Sanctuary: Holy Word: Sanctuary when three allies are hurt, Renew, Circle of Healing, Prayer
--     of Mending, Prayer of Healing, then Binding Heal and Flash Heal only in emergencies.
--     Otherwise: Renew, Holy Word: Serenity, Prayer of Mending, Greater Heal, Heal, Binding Heal,
--     Flash Heal, Power Word: Shield last, and Flash Heal as the filler before you learn Heal. Same
--     switch, reminders and damage list as the recommended Holy premade; enable it and disable that
--     one to use it.
[40] = "Standardmäßig deaktiviert. Die Heilig-Reihenfolge von Icy Veins, gewählt nach Ihrem Chakra. In Chakra: Refugium: Segenswort: Refugium, wenn drei Verbündete verletzt sind, Erneuerung, Kreis der Heilung, Gebet der Besserung, Gebet der Heilung, dann Verbindende Heilung und Blitzheilung nur im Notfall. Sonst: Erneuerung, Segenswort: Epiphanie, Gebet der Besserung, Große Heilung, Heilung, Verbindende Heilung, Blitzheilung, Machtwort: Schild zuletzt und Blitzheilung als Füller, bevor Sie Heilung erlernen. Dieselbe Umschaltung, dieselben Erinnerungen und dieselbe Schadensliste wie die empfohlene integrierte Heilig-Rotation; aktivieren Sie sie und deaktivieren Sie die empfohlene, um sie zu verwenden.",
-- 6c0c75e0 English: Shadow damage from level 10 to 90, chosen in the Shadow specialization. Opens
--     with Mind Spike, Mind Blast or your DoTs. Devouring Plague at three Shadow Orbs (when Mind
--     Blast is ready or still six seconds away), Mind Blast, Shadow Word: Death below 20% health,
--     Mind Flay while your Devouring Plague is up if you took Solace and Insanity, Shadow Word:
--     Pain and Vampiric Touch refreshed near the end on a target that will live, Mind Spike on
--     Surge of Darkness, Halo, Cascade or Divine Star at their best range, then Mind Flay. A Mind
--     Flay is cut short for Mind Blast or Shadow Word: Death, or after its second tick; other
--     channels are never interrupted. While moving it suggests instants only. On five or more
--     enemies: your tier-6 talent, DoTs on your target and Mind Sear. Reminders: Shadowform, Inner
--     Fire, Fortitude, Silence on interruptible casts, Shadowfiend or Mindbender and Power Infusion
--     on long fights, Vampiric Embrace, Desperate Prayer and Dispersion when low. Left to you: DoTs
--     on other targets and where Mind Sear lands.
[41] = "Schattenschaden von Stufe 10 bis 90, gewählt in der Spezialisierung Schatten. Eröffnet mit Gedankenstachel, Gedankenschlag oder Ihren DoTs. Verschlingende Seuche bei drei Schattenkugeln (wenn Gedankenschlag bereit oder noch sechs Sekunden entfernt ist), Gedankenschlag, Schattenwort: Tod unter 20 % Gesundheit, Gedankenschinden, solange Ihre Verschlingende Seuche aktiv ist, wenn Sie Trost und Wahnsinn gewählt haben, Schattenwort: Schmerz und Vampirberührung kurz vor dem Ende auf einem Ziel erneuert, das lange genug lebt, Gedankenstachel bei Woge der Dunkelheit, Strahlenkranz, Kaskade oder Göttlicher Stern in ihrer besten Reichweite, dann Gedankenschinden. Ein Gedankenschinden wird für Gedankenschlag oder Schattenwort: Tod oder nach seinem zweiten Tick abgebrochen; andere Kanalisierungen werden nie unterbrochen. In Bewegung schlägt sie nur Spontanzauber vor. Gegen fünf oder mehr Gegner: Ihr Talent der Stufe 6, DoTs auf Ihrem Ziel und Gedankenexplosion. Erinnerungen: Schattengestalt, Inneres Feuer, Seelenstärke, Stille bei unterbrechbaren Zaubern, Schattengeist oder Geistbeuger und Seele der Macht bei langen Kämpfen, Vampirumarmung, Verzweifeltes Gebet und Dispersion bei niedriger Gesundheit. Ihnen überlassen: DoTs auf anderen Zielen und wo Gedankenexplosion landet.",
-- 298fc327 English: No Insanity priority (Warcraft Tavern)
[42] = "Ohne Wahnsinn-Priorität (Warcraft Tavern)",
-- 0e01e728 English: Off by default. Warcraft Tavern's Shadow order: Devouring Plague at three
--     Shadow Orbs, Shadow Word: Death below 20%, Mind Blast, Vampiric Touch, Shadow Word: Pain,
--     Mind Spike on Surge of Darkness, your tier-6 talent, Mind Flay. Unlike the recommended Shadow
--     premade it never raises Mind Flay under Devouring Plague and does not hold Devouring Plague
--     for Mind Blast. Same opener, movement, pack and reminder steps; enable it and disable the
--     recommended one to use it.
[43] = "Standardmäßig deaktiviert. Die Schatten-Reihenfolge von Warcraft Tavern: Verschlingende Seuche bei drei Schattenkugeln, Schattenwort: Tod unter 20 %, Gedankenschlag, Vampirberührung, Schattenwort: Schmerz, Gedankenstachel bei Woge der Dunkelheit, Ihr Talent der Stufe 6, Gedankenschinden. Anders als die empfohlene integrierte Schattenrotation zieht sie Gedankenschinden während Verschlingender Seuche nie vor und hält Verschlingende Seuche nicht für Gedankenschlag zurück. Dieselben Schritte für Eröffnung, Bewegung, Gruppen und Erinnerungen; aktivieren Sie sie und deaktivieren Sie die empfohlene, um sie zu verwenden.",
-- 31c78194 English: For levels 1 to 9, or any priest who has not chosen a specialization yet. On an
--     enemy: Shadow Word: Pain when it will live long enough, then Smite. On a friend: Flash Heal
--     when they are low, otherwise Power Word: Shield. Reminders: Inner Fire, and a shield on
--     yourself when you are solo and hurt. Choosing a specialization at 10 switches to its own
--     premade.
[44] = "Für Stufe 1 bis 9 oder jeden Priester, der noch keine Spezialisierung gewählt hat. Gegen einen Gegner: Schattenwort: Schmerz, wenn er lange genug lebt, dann Heilige Pein. Auf einen Verbündeten: Blitzheilung, wenn er wenig Gesundheit hat, sonst Machtwort: Schild. Erinnerungen: Inneres Feuer und ein Schild auf Ihnen selbst, wenn Sie solo und verletzt sind. Die Wahl einer Spezialisierung auf Stufe 10 wechselt zu deren eigener integrierter Rotation.",
}
